never sees the page's CSS, so the theme.css tokens are restated here. */
   svg{--rambo:#146272;--rambo-deep:#004552;--rambo-tint:#4a939f;--accent:#9f682e}
   @media (prefers-color-scheme:dark){svg{--rambo:#64bbc4;--rambo-deep:#358e9b;--rambo-tint:#a3dde0;--accent:#d9a45c}}
   svg{--rambo-barrel:var(--rambo);--rambo-cap:var(--accent);--rambo-nib:var(--accent);--rambo-lead:var(--rambo-deep);--rambo-ink:var(--rambo-deep);--rambo-eye:#FCFAF4;--rambo-pupil:var(--rambo-deep);--rambo-blush:#D08770;--rambo-fx:var(--rambo-tint);--rambo-brow:var(--rambo-deep)}
   .pen-barrel{fill:var(--rambo-barrel)}
   .pen-cap{fill:var(--rambo-cap)}
   .pen-nib{fill:var(--rambo-nib)}
   .pen-lead{fill:var(--rambo-lead)}
   .pen-gloss{stroke:rgba(255,255,255,.35);stroke-width:2.4;stroke-linecap:round;fill:none}
   .eye-white{fill:var(--rambo-eye)}
   .eye-black{fill:var(--rambo-pupil)}
   .brow{stroke:var(--rambo-brow);stroke-width:2;stroke-linecap:round;fill:none}
   .mouth{stroke:var(--rambo-lead);stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;fill:none}
   .mouth-fill{fill:var(--rambo-lead)}
   .tongue{fill:var(--rambo-blush)}
   .lid{fill:var(--rambo-barrel)}
   .blush{fill:var(--rambo-blush);opacity:.45}
   .ink-drop{fill:var(--rambo-ink)}
   .fx{stroke:var(--rambo-fx);stroke-width:1.6;stroke-linecap:round;fill:none}
   .fx-fill{fill:var(--rambo-fx)}
   .pen-grain{stroke:var(--rambo-fx);stroke-width:1;stroke-linecap:round;fill:none}
   .pen-eraser{fill:var(--rambo-blush)}
